//! Sea zones (`assets/map/seas.ron`, generated by `bf-mapgen seas`): the zones of the oceans,
//! their contacts, the ports (coastal states and the zones they touch) and the straits and
//! canals, which are edges someone can close. Not wired into the simulation yet: the war (convoys,
//! blockade, landings) and the trade of phase 4 will route over it. See
//! `docs/map-pipeline.pt-BR.md`, "Zonas marítimas".
//!
//! Distances are rough: zone to zone between the zones' poles of inaccessibility, port to zone
//! from the state's centre. A port's weight is only geometry (pixels of coast on the zone); its
//! capacity comes later, with the port infrastructure of the economy.

use std::cmp::Reverse;
use std::collections::{BTreeMap, BTreeSet, BinaryHeap};

use serde::{Deserialize, Serialize};

/// Sea ice in the zone, by the norm of the 20th century.
#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord, Hash, Serialize, Deserialize)]
pub enum Ice {
    Free,
    /// Closed in the northern winter without icebreakers.
    Seasonal,
    /// Closed all year without icebreakers.
    Permanent,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord, Hash, Serialize, Deserialize)]
pub enum PassageKind {
    Strait,
    Canal,
}

#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
pub struct SeasFile {
    pub meta: SeaMeta,
    pub zones: Vec<ZoneDef>,
    /// Contacts between zones, one per pair, and one per strait or canal.
    pub edges: Vec<EdgeDef>,
    pub ports: Vec<PortDef>,
    pub straits: Vec<StraitDef>,
}

#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
pub struct SeaMeta {
    pub sources: Vec<String>,
    /// Marine polygons the rules do not name (their water joins the nearest zone).
    pub unlisted_features: u32,
}

#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
pub struct ZoneDef {
    /// 1..N, the pixel value in `seas.png`.
    pub id: u16,
    pub key: String,
    pub name: String,
    /// Pole of inaccessibility, in texture pixels.
    pub center: (f32, f32),
    pub lon_lat: (f32, f32),
    pub pixels: u32,
    pub ice: Ice,
    pub ice_source: String,
    /// A sea with no way out (the Caspian).
    pub isolated: bool,
}

#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
pub struct EdgeDef {
    pub a: u16,
    pub b: u16,
    /// Great-circle distance between the zones' centres.
    pub km: f32,
    /// Pixel edges the two zones share (0 for a strait the texture does not resolve).
    pub contact: u32,
    /// The strait or canal this edge is; `None` for an open contact.
    pub strait: Option<u16>,
}

#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
pub struct PortDef {
    /// State id in `provinces.ron`.
    pub state: u16,
    pub zone: u16,
    /// Pixel edges of the state's coast on the zone: geometry only, not capacity.
    pub coast: u32,
    /// From the state's centre to the zone's centre.
    pub km: f32,
}

#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
pub struct StraitDef {
    pub id: u16,
    pub key: String,
    pub name: String,
    pub kind: PassageKind,
    pub a: u16,
    pub b: u16,
    /// States on the shores; the controllers are their owners at the time.
    pub shores: Vec<u16>,
    /// ISO date a canal opened.
    pub opened: Option<String>,
    /// Treaty that governs passage, with its source (reference for phase 4).
    pub regime: Option<String>,
    pub source: String,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Season {
    /// Northern summer: seasonal ice is open.
    Summer,
    /// Northern winter: seasonal ice closes without icebreakers.
    Winter,
}

/// What a route may use.
#[derive(Clone, Debug)]
pub struct RouteOptions {
    /// Straits and canals closed (see [`SeaGraph::closed_by`]).
    pub closed: BTreeSet<u16>,
    pub season: Season,
    /// The ships have icebreakers: seasonal and permanent ice are open.
    pub icebreakers: bool,
    /// ISO date: canals not open yet are closed.
    pub date: String,
}

impl RouteOptions {
    pub fn open(date: &str) -> Self {
        Self {
            closed: BTreeSet::new(),
            season: Season::Summer,
            icebreakers: false,
            date: date.to_string(),
        }
    }
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Route {
    /// Zones crossed, from the first port's zone to the last.
    pub zones: Vec<u16>,
    /// Straits and canals passed.
    pub straits: Vec<u16>,
    pub km: u32,
}

/// The sea graph, ready to route.
#[derive(Clone, Debug)]
pub struct SeaGraph {
    pub file: SeasFile,
    /// Per zone (index = id), neighbours: (zone, km, strait).
    adjacency: Vec<Vec<(u16, u32, Option<u16>)>>,
    /// Per state id, its ports: (zone, km).
    ports: BTreeMap<u16, Vec<(u16, u32)>>,
}

impl SeaGraph {
    pub fn new(file: SeasFile) -> Result<Self, String> {
        let n = file.zones.len();
        for (i, z) in file.zones.iter().enumerate() {
            if z.id as usize != i + 1 {
                return Err(format!("zone {}: id {} out of order", z.key, z.id));
            }
        }
        let mut adjacency = vec![Vec::new(); n + 1];
        for e in &file.edges {
            if e.a == 0 || e.b == 0 || e.a as usize > n || e.b as usize > n {
                return Err(format!("edge {}–{}: unknown zone", e.a, e.b));
            }
            let km = e.km.max(0.0).round() as u32;
            adjacency[e.a as usize].push((e.b, km, e.strait));
            adjacency[e.b as usize].push((e.a, km, e.strait));
        }
        for list in &mut adjacency {
            list.sort();
        }
        let mut ports: BTreeMap<u16, Vec<(u16, u32)>> = BTreeMap::new();
        for p in &file.ports {
            ports
                .entry(p.state)
                .or_default()
                .push((p.zone, p.km.max(0.0).round() as u32));
        }
        Ok(Self {
            file,
            adjacency,
            ports,
        })
    }

    pub fn zone(&self, key: &str) -> Option<u16> {
        self.file.zones.iter().find(|z| z.key == key).map(|z| z.id)
    }

    pub fn strait(&self, key: &str) -> Option<u16> {
        self.file
            .straits
            .iter()
            .find(|s| s.key == key)
            .map(|s| s.id)
    }

    pub fn is_coastal(&self, state: u16) -> bool {
        self.ports.contains_key(&state)
    }

    pub fn ports_of(&self, state: u16) -> &[(u16, u32)] {
        self.ports.get(&state).map_or(&[], Vec::as_slice)
    }

    /// Who controls each strait: the owners of its shore states, given the owner of each state.
    pub fn controllers<'a>(
        &self,
        strait: u16,
        owner: impl Fn(u16) -> &'a str,
    ) -> BTreeSet<&'a str> {
        self.file.straits[strait as usize]
            .shores
            .iter()
            .map(|s| owner(*s))
            .collect()
    }

    /// Straits closed when the countries in `closers` close everything they control. Any one
    /// owner of a shore can close a strait: a battery, a minefield or a fleet on one side is
    /// enough (`docs/map-pipeline.pt-BR.md`, "Quem controla").
    pub fn closed_by<'a>(
        &self,
        closers: &BTreeSet<&str>,
        owner: impl Fn(u16) -> &'a str + Copy,
    ) -> BTreeSet<u16> {
        self.file
            .straits
            .iter()
            .filter(|s| {
                self.controllers(s.id, owner)
                    .iter()
                    .any(|c| closers.contains(c))
            })
            .map(|s| s.id)
            .collect()
    }

    fn zone_open(&self, zone: u16, o: &RouteOptions) -> bool {
        match self.file.zones[zone as usize - 1].ice {
            Ice::Free => true,
            Ice::Seasonal => o.icebreakers || o.season == Season::Summer,
            Ice::Permanent => o.icebreakers,
        }
    }

    fn strait_open(&self, strait: u16, o: &RouteOptions) -> bool {
        let s = &self.file.straits[strait as usize];
        !o.closed.contains(&strait) && s.opened.as_deref().is_none_or(|d| d <= o.date.as_str())
    }

    /// The shortest sea route between two states' ports, or `None` when no open port of one
    /// reaches an open port of the other. Ties go to the lower zone id.
    pub fn route(&self, from: u16, to: u16, o: &RouteOptions) -> Option<Route> {
        let n = self.file.zones.len();
        let mut dist = vec![u32::MAX; n + 1];
        let mut prev: Vec<Option<(u16, Option<u16>)>> = vec![None; n + 1];
        let mut heap = BinaryHeap::new();
        for &(z, km) in self.ports_of(from) {
            if self.zone_open(z, o) && km < dist[z as usize] {
                dist[z as usize] = km;
                heap.push(Reverse((km, z)));
            }
        }
        while let Some(Reverse((d, z))) = heap.pop() {
            if d > dist[z as usize] {
                continue;
            }
            for &(y, km, strait) in &self.adjacency[z as usize] {
                if !self.zone_open(y, o) || strait.is_some_and(|s| !self.strait_open(s, o)) {
                    continue;
                }
                let nd = d.saturating_add(km);
                if nd < dist[y as usize] {
                    dist[y as usize] = nd;
                    prev[y as usize] = Some((z, strait));
                    heap.push(Reverse((nd, y)));
                }
            }
        }
        let (end, km) = self
            .ports_of(to)
            .iter()
            .filter(|(z, _)| dist[*z as usize] != u32::MAX)
            .map(|&(z, km)| (z, dist[z as usize].saturating_add(km)))
            .min_by_key(|&(z, km)| (km, z))?;
        let mut zones = vec![end];
        let mut straits = Vec::new();
        let mut at = end;
        while let Some((p, s)) = prev[at as usize] {
            zones.push(p);
            straits.extend(s);
            at = p;
        }
        zones.reverse();
        straits.reverse();
        Some(Route { zones, straits, km })
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn zone(id: u16, key: &str, ice: Ice) -> ZoneDef {
        ZoneDef {
            id,
            key: key.into(),
            name: key.into(),
            center: (0.0, 0.0),
            lon_lat: (0.0, 0.0),
            pixels: 1,
            ice,
            ice_source: String::new(),
            isolated: false,
        }
    }

    fn edge(a: u16, b: u16, km: f32, strait: Option<u16>) -> EdgeDef {
        EdgeDef {
            a,
            b,
            km,
            contact: 1,
            strait,
        }
    }

    fn port(state: u16, zone: u16) -> PortDef {
        PortDef {
            state,
            zone,
            coast: 1,
            km: 100.0,
        }
    }

    /// Two seas joined by a short strait and by a long way round; a frozen bay off the first.
    fn graph() -> SeaGraph {
        SeaGraph::new(SeasFile {
            meta: SeaMeta {
                sources: vec![],
                unlisted_features: 0,
            },
            zones: vec![
                zone(1, "west", Ice::Free),
                zone(2, "east", Ice::Free),
                zone(3, "ocean", Ice::Free),
                zone(4, "bay", Ice::Seasonal),
            ],
            edges: vec![
                edge(1, 2, 500.0, Some(0)),
                edge(1, 3, 2000.0, None),
                edge(2, 3, 2000.0, None),
                edge(1, 4, 300.0, None),
            ],
            ports: vec![port(10, 1), port(20, 2), port(30, 4), port(11, 1)],
            straits: vec![StraitDef {
                id: 0,
                key: "narrows".into(),
                name: "Narrows".into(),
                kind: PassageKind::Strait,
                a: 1,
                b: 2,
                shores: vec![10, 20],
                opened: None,
                regime: None,
                source: String::new(),
            }],
        })
        .unwrap()
    }

    #[test]
    fn closing_a_strait_sends_the_route_round() {
        let g = graph();
        let open = g.route(10, 20, &RouteOptions::open("1925-01-01")).unwrap();
        assert_eq!(open.zones, vec![1, 2]);
        assert_eq!(open.straits, vec![0]);
        assert_eq!(open.km, 700);
        let mut o = RouteOptions::open("1925-01-01");
        o.closed.insert(0);
        let round = g.route(10, 20, &o).unwrap();
        assert_eq!(round.zones, vec![1, 3, 2]);
        assert_eq!(round.km, 4200);
        assert!(round.straits.is_empty());
    }

    #[test]
    fn either_shore_closes_the_strait() {
        let g = graph();
        let owner = |s: u16| if s == 10 || s == 11 { "AAA" } else { "BBB" };
        assert_eq!(g.controllers(0, owner), BTreeSet::from(["AAA", "BBB"]));
        assert_eq!(
            g.closed_by(&BTreeSet::from(["BBB"]), owner),
            BTreeSet::from([0])
        );
        assert_eq!(
            g.closed_by(&BTreeSet::from(["AAA"]), owner),
            BTreeSet::from([0])
        );
        assert!(g.closed_by(&BTreeSet::from(["CCC"]), owner).is_empty());
        // When both shores change hands, control follows the owner.
        let taken = |_: u16| "CCC";
        assert_eq!(
            g.closed_by(&BTreeSet::from(["CCC"]), taken),
            BTreeSet::from([0])
        );
    }

    #[test]
    fn ice_closes_a_seasonal_port_in_winter_unless_icebreakers() {
        let g = graph();
        let mut o = RouteOptions::open("1925-01-01");
        assert!(g.route(30, 20, &o).is_some());
        o.season = Season::Winter;
        assert!(g.route(30, 20, &o).is_none());
        assert!(g.route(10, 20, &o).is_some());
        o.icebreakers = true;
        assert!(g.route(30, 20, &o).is_some());
    }

    #[test]
    fn canals_open_on_their_date_and_same_zone_ports_meet() {
        let mut g = graph();
        g.file.straits[0].kind = PassageKind::Canal;
        g.file.straits[0].opened = Some("1914-08-15".into());
        assert_eq!(
            g.route(10, 20, &RouteOptions::open("1913-01-01"))
                .unwrap()
                .km,
            4200
        );
        assert_eq!(
            g.route(10, 20, &RouteOptions::open("1925-01-01"))
                .unwrap()
                .km,
            700
        );
        let r = g.route(10, 11, &RouteOptions::open("1925-01-01")).unwrap();
        assert_eq!((r.zones, r.km), (vec![1], 200));
        assert!(g.route(10, 99, &RouteOptions::open("1925-01-01")).is_none());
    }
}
